describe('Logo Navigation to Home Page', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate to home page when logo is clicked', () => {
    cy.get('[data-testid="logo"]').should('be.visible').click();
    cy.url().should('eq', Cypress.config().baseUrl + '/');
    cy.get('h1').should('contain', 'Home');
  });

  it('should navigate to home page from any internal page when logo is clicked', () => {
    cy.visit('/about');
    cy.get('[data-testid="logo"]').should('be.visible').click();
    cy.url().should('eq', Cypress.config().baseUrl + '/');
    cy.get('h1').should('contain', 'Home');
  });

  it('should handle logo click when logo is disabled or hidden gracefully', () => {
    cy.get('[data-testid="logo"]').then(($logo) => {
      if ($logo.is(':visible')) {
        cy.wrap($logo).click();
        cy.url().should('include', '/');
      } else {
        cy.wrap($logo).should('not.be.visible');
      }
    });
  });

  it('should maintain logo accessibility with proper alt text', () => {
    cy.get('[data-testid="logo"]').should('have.attr', 'alt').and('not.be.empty');
  });

  it('should have clickable logo with proper cursor styling', () => {
    cy.get('[data-testid="logo"]').should('have.css', 'cursor', 'pointer');
  });
});
